# ==========================================================================
# WineMetalScan -- metal concentration estimation in wine by FT-MIR
# spectroscopy and machine learning. App for Posit Connect Cloud.
#
# Structure:
#   - One tab per analyte (potassium, magnesium, calcium, iron, copper).
#   - Each tab: scope / instrument / EDTA protocol information, model
#     validation status (metrics + plots of the winning model), and a
#     panel to upload a spectrum and get a prediction.
#   - Models are loaded at runtime from Models/*.rds (generated by
#     Build_Deployment_Models.R). If an .rds is not yet available, the
#     tab reports that instead of crashing.
# ==========================================================================

library(shiny)
library(bslib)
library(DT)
library(ggplot2)
library(openxlsx)

source("R/predict_utils.R")

MODELS_DIR <- "Models"
DATA_DIR   <- "data"

# --------------------------------------------------------------------
# Information common to the five analytes (instrument, reference
# method, Na2EDTA sample-preparation protocol, varietal/geographic
# scope).
# --------------------------------------------------------------------
COMMON_INFO <- list(
  instrument = paste(
    "Spectra acquired in duplicate with a MultiSpec system (TDI, Barcelona,",
    "Spain), equipped with a CETIM flow-through transmission cell (TDI,",
    "Barcelona, Spain) and a 40-position autosampler. Spectral range:",
    "902.57-3000.84 cm-1 (545 variables, ~3.86 cm-1 step)."),
  reference_method = paste(
    "Reference concentrations were determined by inductively coupled plasma",
    "optical emission spectrometry (ICP-OES), Spectrogreen FMD46 instrument",
    "(SPECTRO Analytical Instruments)."),
  edta_protocol = paste(
    "Sample preparation: add 2 mL of a 5% w/v aqueous Na2EDTA solution to 8 mL",
    "of wine (final volume 10 mL). Mix gently and let stand for 30 minutes at",
    "room temperature before measuring. The addition of Na2EDTA is necessary",
    "because metals do not absorb directly in the infrared; the formation of",
    "the metal-EDTA complex is what produces the spectral signal used by the",
    "model."),
  wine_scope = paste(
    "Spanish white and red wines from 20 Designations of Origin (Cadiz, Borja,",
    "Carinena, Castilla, Catalunya, Extremadura, Jumilla, La Jaraba, La Mancha,",
    "Madrid, Navarra, Penedes, Ribeiro, Ribera del Duero, Rioja, Rueda,",
    "Somontano, Toro, Ucles and Valdepenas) and 9 grape varieties (Airen,",
    "Garnacha, Merlot, Monastrell, Palomino, Sauvignon Blanc, Tempranillo,",
    "Verdejo and Viura)."),
  disclaimer = paste(
    "The values returned by this tool are ESTIMATES obtained with machine",
    "learning algorithms from the FT-MIR spectrum, and should be treated as",
    "INDICATIVE or screening values. They do not replace analysis by",
    "reference methods (ICP-OES/ICP-MS or other official OIV methods) and",
    "must not be used as the sole basis for enological, regulatory or",
    "commercial decisions.")
)

IVAGRO_URL <- "https://ivagro.uca.es"
APP_CODE_URL   <- "https://github.com/pablofacu86/WineMetalScan"
STUDY_CODE_URL <- "https://github.com/pablofacu86/Wine-Metals-FTMIR-ML"

