# --------------------------------------------------------------------
# Lazy, cached loading of each .rds bundle. Returns NULL (without
# crashing the app) if the file has not been generated yet.
# --------------------------------------------------------------------
.bundle_cache <- new.env(parent = emptyenv())
load_bundle <- function(analyte_key) {
  if (!is.null(.bundle_cache[[analyte_key]])) return(.bundle_cache[[analyte_key]])
  path <- ANALYTES[[analyte_key]]$model_file
  if (!file.exists(path)) return(NULL)
  b <- readRDS(path)
  .bundle_cache[[analyte_key]] <- b
  b
}

# --------------------------------------------------------------------
# Downloadable report (self-contained HTML) with the model's detail:
# scope, method, preprocessing, hyperparameters and metrics.
# --------------------------------------------------------------------
render_model_report_html <- function(cfg, bundle) {
  metric_rows <- if (cfg$task == "regression") {
    m <- bundle$metrics
    sprintf(
      "<tr><td>R\u00b2 (test)</td><td>%.3f</td></tr><tr><td>RMSE (test)</td><td>%.2f %s</td></tr>
       <tr><td>RPD (test)</td><td>%.2f</td></tr><tr><td>R\u00b2 (training)</td><td>%.3f</td></tr>
       <tr><td>RMSE (training)</td><td>%.2f %s</td></tr>",
      m$R2_Test, m$RMSE_Test, cfg$unit, m$RPD_Test, m$R2_Train, m$RMSE_Train, cfg$unit)
  } else {
    m <- bundle$metrics
    sprintf(
      "<tr><td>AUC (test)</td><td>%s</td></tr><tr><td>Accuracy (test)</td><td>%.3f</td></tr>
       <tr><td>Kappa (test)</td><td>%.3f</td></tr><tr><td>Sensitivity (test)</td><td>%.3f</td></tr>
       <tr><td>Specificity (test)</td><td>%.3f</td></tr>",
      ifelse(is.na(m$AUC_Test), "N/A", sprintf("%.3f", m$AUC_Test)),
      m$Accuracy_Test, m$Kappa_Test, m$Sensitivity_Test, m$Specificity_Test)
  }
  hp <- paste(sprintf("%s = %s", names(bundle$hyperparams), unlist(bundle$hyperparams)), collapse = "; ")
  sprintf('<html><head><meta charset="utf-8"><style>
    body{font-family:Arial,Helvetica,sans-serif;max-width:800px;margin:2em auto;color:#222}
    h1{color:%s} table{border-collapse:collapse;width:100%%;margin:1em 0}
    td,th{border:1px solid #ccc;padding:6px 10px;text-align:left} th{background:#f2f2f2}
    .disclaimer{background:#fff3cd;border:1px solid #ffe08a;padding:1em;border-radius:6px;margin-top:2em}
  </style></head><body>
  <h1>WineMetalScan &mdash; Model sheet: %s (%s)</h1>
  <p><i>Generated: %s</i></p>
  <h2>Scope</h2>
  <table><tr><th>Validated range</th><td>%s</td></tr>
  <tr><th>No. of samples (total)</th><td>%s</td></tr>
  <tr><th>No. training / test</th><td>%d / %d</td></tr>
  <tr><th>Varieties and origin</th><td>%s</td></tr></table>
  <h2>Instrument and reference method</h2>
  <table><tr><th>FT-MIR</th><td>%s</td></tr>
  <tr><th>Reference method</th><td>%s</td></tr></table>
  <h2>Sample preparation (Na<sub>2</sub>EDTA)</h2>
  <p>%s</p>
  <h2>Model</h2>
  <table><tr><th>Algorithm and preprocessing</th><td>%s</td></tr>
  <tr><th>Hyperparameters</th><td>%s</td></tr></table>
  <h2>Performance metrics</h2>
  <table><tr><th>Metric</th><th>Value</th></tr>%s</table>
  <div class="disclaimer"><b>Disclaimer:</b> %s</div>
  </body></html>',
  cfg$color, cfg$label, cfg$symbol, format(Sys.time(), "%Y-%m-%d %H:%M"),
  cfg$scope_range, cfg$n_samples, bundle$n_train, bundle$n_test, COMMON_INFO$wine_scope,
  COMMON_INFO$instrument, COMMON_INFO$reference_method, COMMON_INFO$edta_protocol,
  cfg$model_desc, hp, metric_rows, COMMON_INFO$disclaimer)
}

render_prediction_report_html <- function(cfg, result) {
  body <- if (result$task == "regression") {
    sprintf("<p style='font-size:1.4em'><b>%.1f %s</b> (approx. 95%% interval: %.1f - %.1f %s)</p>
             <p>Estimated uncertainty: &plusmn; 2 &times; test RMSE (%.1f %s).</p>",
            result$value, cfg$unit, result$lower, result$upper, cfg$unit, result$uncertainty / 2, cfg$unit)
  } else {
    probs <- paste(sprintf("%s: %.1f%%", names(result$probabilities), as.numeric(result$probabilities) * 100), collapse = "<br>")
    sprintf("<p style='font-size:1.4em'><b>%s</b></p><p>Class probabilities:<br>%s</p>", result$class, probs)
  }
  resample_note <- if (isTRUE(result$resampled)) {
    "<p><i>Note: the uploaded spectrum did not match the model's reference grid; it was resampled by linear interpolation before prediction.</i></p>"
  } else ""
  sprintf('<html><head><meta charset="utf-8"><style>
    body{font-family:Arial,Helvetica,sans-serif;max-width:700px;margin:2em auto;color:#222}
    h1{color:%s} .disclaimer{background:#fff3cd;border:1px solid #ffe08a;padding:1em;border-radius:6px;margin-top:2em}
  </style></head><body>
  <h1>WineMetalScan &mdash; Prediction result: %s (%s)</h1>
  <p><i>Generated: %s</i></p>
  %s %s
  <div class="disclaimer"><b>Disclaimer:</b> %s</div>
  </body></html>',
  cfg$color, cfg$label, cfg$symbol, format(Sys.time(), "%Y-%m-%d %H:%M"), body, resample_note,
  COMMON_INFO$disclaimer)
}

# ==========================================================================
# Shiny module: one full tab per analyte
# ==========================================================================
analyteUI <- function(id, cfg) {
  ns <- NS(id)
  tagList(
    layout_columns(
      col_widths = c(4, 8),
      # ---------------- Left column: scope and downloads ----------------
      card(
        card_header(style = sprintf("background:%s;color:white;font-weight:600;", cfg$color),
                     sprintf("%s (%s) \u2014 Scope and traceability", cfg$label, cfg$symbol)),
        card_body(
          tags$table(class = "table table-sm",
            tags$tr(tags$td(tags$b("Validated range")), tags$td(cfg$scope_range)),
            tags$tr(tags$td(tags$b("Samples")), tags$td(cfg$n_samples)),
            tags$tr(tags$td(tags$b("Winning model")), tags$td(cfg$model_desc))
          ),
          if (isTRUE(cfg$spiked))
            div(class = "alert alert-secondary", style = "font-size:0.9em",
                "Part of the validation range was obtained by spiking commercial wines with the analyte of interest, ",
                "to cover concentrations rarely found in the natural matrix. See the model sheet for details."),
          tags$hr(),
          tags$b("Grape varieties and origin"), tags$p(COMMON_INFO$wine_scope, style = "font-size:0.9em"),
          tags$b("FT-MIR instrument"), tags$p(COMMON_INFO$instrument, style = "font-size:0.9em"),
          tags$b("Reference method (true values)"), tags$p(COMMON_INFO$reference_method, style = "font-size:0.9em"),
          tags$hr(),
          accordion(
            open = FALSE,
            accordion_panel("Sample preparation protocol (Na\u2082EDTA)",
                             p(COMMON_INFO$edta_protocol))
          ),
          tags$hr(),
          downloadButton(ns("dl_sample"), "Download validation dataset", class = "btn-outline-secondary btn-sm w-100 mb-2"),
          downloadButton(ns("dl_model_html"), "Download model summary sheet", class = "btn-outline-secondary btn-sm w-100"),
          tags$hr(),
          div(class = "alert alert-warning", style = "font-size:0.85em", COMMON_INFO$disclaimer)
        )
      ),
      # ---------------- Right column: validation + prediction ----------------
      div(
        card(
          card_header("Model validation status"),
          card_body(
            actionButton(ns("btn_validate"), "View validation status", class = "btn-primary mb-3"),
            uiOutput(ns("validation_ui"))
          )
        ),
        card(
          card_header("Predict from your own spectrum"),
          card_body(
            p("Upload an FT-MIR spectrum (902.57 to 3000.84 cm\u207b\u00b9). .csv or .xlsx with two columns ",
              "(wavenumber, absorbance) is accepted, or the same row format as the study's datasets.",
              style = "font-size:0.9em; color:#555"),
            fileInput(ns("spectrum_file"), NULL, accept = c(".csv", ".xlsx")),
            actionButton(ns("btn_predict"), "Predict", class = "btn-primary mb-3"),
            uiOutput(ns("prediction_ui"))
          )
        )
      )
    )
  )
}

analyteServer <- function(id, cfg) {
  moduleServer(id, function(input, output, session) {

    bundle <- reactive(load_bundle(id))

    # ---------------- Downloads ----------------
    output$dl_sample <- downloadHandler(
      filename = function() sprintf("Validation_samples_%s.xlsx", cfg$symbol),
      content = function(file) file.copy(cfg$sample_file, file)
    )
    output$dl_model_html <- downloadHandler(
      filename = function() sprintf("Model_sheet_%s.html", cfg$symbol),
      content = function(file) {
        b <- bundle()
        validate(need(!is.null(b), "The model is not available yet."))
        writeLines(render_model_report_html(cfg, b), file)
      }
    )

    # ---------------- Validation status ----------------
    output$validation_ui <- renderUI({
      req(input$btn_validate > 0)
      b <- bundle()
      ns <- session$ns
      if (is.null(b)) {
        return(div(class = "alert alert-danger",
                    "The model for this analyte is not loaded on the server yet."))
      }
      if (cfg$task == "regression") {
        tagList(
          h5("Winning model hyperparameters"),
          p(paste(sprintf("%s = %s", names(b$hyperparams), unlist(b$hyperparams)), collapse = "; ")),
          DTOutput(ns("metrics_table")),
          plotOutput(ns("scatter_plot"), height = "380px")
        )
      } else {
        tagList(
          h5("Winning model hyperparameters"),
          p(paste(sprintf("%s = %s", names(b$hyperparams), unlist(b$hyperparams)), collapse = "; ")),
          DTOutput(ns("metrics_table")),
          plotOutput(ns("confusion_plot"), height = "320px"),
          tags$hr(),
          h5("Hierarchical clustering of the samples (unsupervised)"),
          p("Compares whether the groups formed by the spectrum alone (branch colour) match the actual class (label colour).",
            style = "font-size:0.85em;color:#666"),
          plotOutput(ns("dendrogram_plot"), height = "480px")
        )
      }
    })

    output$metrics_table <- renderDT({
      req(input$btn_validate > 0)
      b <- bundle(); validate(need(!is.null(b), "Model not available."))
      m <- b$metrics
      df <- if (cfg$task == "regression") {
        data.frame(Metric = c("R\u00b2", "RMSE", "RPD"),
                   Training = c(round(m$R2_Train, 3), round(m$RMSE_Train, 2), round(m$RPD_Train, 2)),
                   Test = c(round(m$R2_Test, 3), round(m$RMSE_Test, 2), round(m$RPD_Test, 2)))
      } else {
        data.frame(Metric = c("AUC", "Accuracy", "Kappa", "Sensitivity", "Specificity"),
                   Test = c(round(m$AUC_Test, 3), round(m$Accuracy_Test, 3), round(m$Kappa_Test, 3),
                            round(m$Sensitivity_Test, 3), round(m$Specificity_Test, 3)))
      }
      datatable(df, options = list(dom = "t", paging = FALSE), rownames = FALSE)
    })

    output$scatter_plot <- renderPlot({
      req(input$btn_validate > 0, cfg$task == "regression")
      b <- bundle(); validate(need(!is.null(b), "Model not available."))
      ggplot(b$scatter_data, aes(x = Actual, y = Predicted, color = Set)) +
        geom_abline(slope = 1, intercept = 0, linetype = "dashed", color = "grey40") +
        geom_point(size = 2.5, alpha = 0.8) +
        scale_color_manual(values = c(Train = "#457B9D", Test = cfg$color)) +
        labs(x = sprintf("Measured %s (%s)", cfg$label, cfg$unit),
             y = sprintf("Predicted %s (%s)", cfg$label, cfg$unit), color = NULL) +
        theme_minimal(base_size = 13)
    })

    output$confusion_plot <- renderPlot({
      req(input$btn_validate > 0, cfg$task == "classification")
      b <- bundle(); validate(need(!is.null(b), "Model not available."))
      te <- b$scatter_data
      cm <- as.data.frame(table(Actual = te$Actual, Predicted = te$Predicted))
      ggplot(cm, aes(x = Actual, y = Predicted, fill = Freq)) +
        geom_tile(color = "white") +
        geom_text(aes(label = Freq), size = 6, fontface = "bold") +
        scale_fill_gradient(low = "#f2f2f2", high = cfg$color) +
        labs(title = "Confusion matrix (test)") +
        theme_minimal(base_size = 12) + theme(axis.text.x = element_text(angle = 20, hjust = 1))
    })

    output$dendrogram_plot <- renderPlot({
      req(input$btn_validate > 0, cfg$task == "classification")
      b <- bundle(); validate(need(!is.null(b), "Model not available."))
      validate(need(!is.null(b$dendro_hc), "Dendrogram not available for this model."))
      render_dendrogram(b, cfg$color, cfg$limit, cfg$unit)
    })

    # ---------------- Prediction on a new spectrum ----------------
    pred_result <- eventReactive(input$btn_predict, {
      b <- bundle()
      validate(need(!is.null(b), "The model for this analyte is not available yet."))
      validate(need(!is.null(input$spectrum_file), "Upload a spectrum first."))
      spec <- tryCatch(read_uploaded_spectrum(input$spectrum_file$datapath),
                        error = function(e) NULL)
      validate(need(!is.null(spec), "Could not read the file. Check the format (wavenumber / absorbance)."))
      predict_spectrum(b, spec$wn, spec$ab)
    })

    output$prediction_ui <- renderUI({
      res <- pred_result()
      ns <- session$ns
      note <- if (isTRUE(res$resampled))
        div(class = "alert alert-info", style = "font-size:0.85em",
            "The uploaded spectrum did not exactly match the model's wavenumber grid; ",
            "it was realigned by interpolation before predicting.")
      else NULL

      if (res$task == "regression") {
        tagList(
          note,
          div(class = "p-3 mb-2", style = sprintf("background:%s10;border-left:4px solid %s;", cfg$color, cfg$color),
              h3(sprintf("%.1f %s", res$value, cfg$unit), style = sprintf("color:%s", cfg$color)),
              p(sprintf("Approximate interval (95%%): %.1f \u2013 %.1f %s", res$lower, res$upper, cfg$unit)),
              p(sprintf("Uncertainty: \u00b1 2\u00d7 test RMSE (\u00b1 %.1f %s)", res$uncertainty / 2, cfg$unit),
                style = "font-size:0.85em;color:#666")
          ),
          downloadButton(ns("dl_prediction"), "Download result (report)", class = "btn-outline-secondary btn-sm")
        )
      } else {
        probs <- res$probabilities
        tagList(
          note,
          div(class = "p-3 mb-2", style = sprintf("background:%s10;border-left:4px solid %s;", cfg$color, cfg$color),
              h3(res$class, style = sprintf("color:%s", cfg$color)),
              lapply(names(probs), function(cl) {
                pct <- round(as.numeric(probs[[cl]]) * 100, 1)
                div(style = "margin-bottom:6px;",
                    span(sprintf("%s: %.1f%%", cl, pct)),
                    div(style = sprintf("background:#eee;border-radius:4px;height:10px;width:100%%;"),
                        div(style = sprintf("background:%s;border-radius:4px;height:10px;width:%s%%;", cfg$color, pct))))
              })
          ),
          downloadButton(ns("dl_prediction"), "Download result (report)", class = "btn-outline-secondary btn-sm")
        )
      }
    })

    output$dl_prediction <- downloadHandler(
      filename = function() sprintf("Prediction_%s_%s.html", cfg$symbol, format(Sys.time(), "%Y%m%d_%H%M")),
      content = function(file) writeLines(render_prediction_report_html(cfg, pred_result()), file)
    )
  })
}

