  nav_panel("Calcium (Ca)", analyteUI("CALCIUM", ANALYTES$CALCIUM)),
  nav_panel("Iron (Fe)", analyteUI("IRON", ANALYTES$IRON)),
  nav_panel("Copper (Cu)", analyteUI("COPPER", ANALYTES$COPPER)),
  nav_spacer(),
  nav_item(tags$a(href = IVAGRO_URL, target = "_blank", "IVAGRO \u2014 University of Cadiz"))
)

# ==========================================================================
# Main server
# ==========================================================================
server <- function(input, output, session) {
  # NOTE: lapply() is used on purpose instead of a plain for() loop. With
  # a for(), the loop variable is shared across iterations and, because
  # Shiny evaluates these functions lazily, all 5 modules would end up
  # referencing the LAST analyte of the loop (a well-known Shiny pitfall
  # when instantiating modules inside a for loop).
  lapply(names(ANALYTES), function(k) analyteServer(k, ANALYTES[[k]]))
}

shinyApp(ui, server)
